input.command:
git branch --show-current && python3 - <<'EOF'
p='scripts/runner.js'
s=open(p).read()
old="const res = spawnSync(pythonBin, args, { stdio: 'inherit', cwd: rootDir });\nprocess.exit(res.status ?? 0);\n"
new="""const res = spawnSync(pythonBin, args, { stdio: 'inherit', cwd: rootDir });

// Falha ao iniciar o processo (ex: python ausente) nao pode virar sucesso
if (res.error) {
  console.error(`Falha ao executar ${pythonBin}: ${res.error.message}`);
  process.exit(1);
}

// Processo morto por sinal (ex: OOM kill) tem status null
if (res.signal) {
  console.error(`${pythonBin} encerrado pelo sinal ${res.signal}`);
  process.exit(1);
}

process.exit(res.status ?? 1);
"""
assert old in s
open(p,'w').write(s.replace(old,new))
EOF
for c in "import sys; sys.exit(0)" "import sys; sys.exit(3)" "import os,signal; os.kill(os.getpid(), signal.SIGKILL)"; do node scripts/runner.js -c "$c"; echo "exit=$?"; done
PATH=/nonexistent /usr/bin/env node -e "1" 2>/dev/null; mv .venv .venv.bak 2>/dev/null; PATH=$(dirname $(which node)) node scripts/runner.js -c "pass"; echo "exit(sem python)=$?"; mv .venv.bak .venv 2>/dev/null; ls -d .venv

